import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"Versioned Updates and Conflict Recovery","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/edit-conflicts","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/edit-conflicts.md","filePath":"en/tutorials/edit-conflicts.md"}'),n={name:"en/tutorials/edit-conflicts.md"};function r(o,e,l,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="versioned-updates-and-conflict-recovery" tabindex="-1">Versioned Updates and Conflict Recovery <a class="header-anchor" href="#versioned-updates-and-conflict-recovery" aria-label="Permalink to &quot;Versioned Updates and Conflict Recovery&quot;">​</a></h1><p>Goal: prevent silent overwrites of mutable resources and return a stable conflict code clients can recover from. Complete <a href="./personal-documents">business transactions</a> and <a href="./library-grants">resource authorization</a>. Idempotent creation does not replace concurrency control.</p><h2 id="put-expected-version-in-the-protocol" tabindex="-1">Put Expected Version in the Protocol <a class="header-anchor" href="#put-expected-version-in-the-protocol" aria-label="Permalink to &quot;Put Expected Version in the Protocol&quot;">​</a></h2><p>Knowledge&#39;s <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">update DTO and Handler</a> accept <code>PUT /api/v1/knowledge/documents/{id}</code> with <code>title / markdown / version</code>. Version must be positive; Session, Origin and CSRF remain required.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">use case</a> holds current Membership and base locks and checks access before a conditional update. Actual SQL excerpt:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> knowledge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">documents</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, markdown </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    updated_by </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid, updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> clock_timestamp()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> knowledge_base_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deleted_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span></span></code></pre></div><p>The full implementation returns the document and appends Audit. Two writers using the same expected version cannot both succeed. Do not SELECT a version in the Handler and then UPDATE unconditionally. Inaccessible resources return 404; Reader writes return 403; an authorized stale save returns <code>409 document.version_conflict</code>.</p><h2 id="commit-and-unknown-results" tabindex="-1">Commit and Unknown Results <a class="header-anchor" href="#commit-and-unknown-results" aria-label="Permalink to &quot;Commit and Unknown Results&quot;">​</a></h2><p>Body, version and Audit commit together. Audit failure rolls version back, permitting the original version after recovery. A response timeout may happen after commit. Do not blindly retry: read current version, compare content and choose the next action explicitly.</p><p>Your resource owns its version field, conditional update and conflict error; Core does not implement optimistic concurrency for every business. If commands also support idempotency, explain replay and expected-version semantics separately.</p><h2 id="verify-two-writers" tabindex="-1">Verify Two Writers <a class="header-anchor" href="#verify-two-writers" aria-label="Permalink to &quot;Verify Two Writers&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/knowledge.rs" target="_blank" rel="noreferrer">HTTP checks</a> coordinate two requests with real PostgreSQL locks, observe one success and one 409, then read the resulting body. They also cover denial and body/version rollback on Audit failure. Use equivalent public checks for your resource and assert stable codes rather than translated messages.</p><h2 id="client-recovery" tabindex="-1">Client Recovery <a class="header-anchor" href="#client-recovery" aria-label="Permalink to &quot;Client Recovery&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">editor View</a> separates draft/base version from server Query data. Background refresh cannot replace drafts or advance the base version. After 409, preserve input, fetch latest data and require explicit merge/keep or discard; neither choice automatically saves.</p><p>After 403/404, disable further saves and query current permission while preserving unsaved text. Previously displayed content cannot be remotely erased; later requests enforce current access. Continue with <a href="./library-grants">resource authorization</a>, <a href="./members">membership locks</a> and the same commit discipline for <a href="./attachments">file publication</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/06-edit-conflicts.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,19)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
